Suppose 
	$$
	A_{1}\overset{\psi_{1}}{\longrightarrow} A_{2}\overset{\psi_{2}}{\longrightarrow} A_{3}\overset{\psi_{3}}{\longrightarrow}\cdots\longrightarrow A:=\varinjlim A_{i}
	$$
	is a simple limit of infinite-dimensional DSH algebras with injective diagonal maps. Suppose that $f$ is a non-invertible element belonging to some $A_{j}$ and that $\epsilon > 0$. Then, there exist $f'\in A_{j}$ with $\|f-f'\|\leq \epsilon$ and $M\in\mathbb{N}$ such that for all $N\in\mathbb{N}$ there exist $j'>j$ satisfying $\mathfrak{s}(A_{j'})>NM$ and unitaries $V,V'\in A_{j'}$ with the following properties:
	\begin{enumerate}
		\item for any $1\leq i\leq  l (j')$ and $1\leq k\leq n_{i}^{j'}$, there is a (possibly empty) open subset $U_{i,k}$ of $X^{j'}_{i}$ containing $B_{i,k}^{j'}$ such that for all $x\in U_{i,k}$, $(V\psi_{j',j}(f')V')_{i}(x)$ has zero crosses at indices $k, k+M, k+2M,\ldots,k+(N-1)M$;
		\item for all $1\leq i\leq l (j')$ and $x\in X^{j'}_{i}$, we have $\mathfrak{r}((V\psi_{j',j}(f')V')_{i}(x))\leq \mathfrak{S}(A_{j})+M-1$ (where, recall, $\mathfrak{S}(A_{j})=\max\{n^{j}_{t}:1\leq t\leq l (j)\}$). 
	\end{enumerate}

Suppose $A$ is a DSH algebra of length $ l $ and that $M,N\in\mathbb{N}$ with $NM<\mathfrak{s}(A)$. Suppose $f$ is an element of $A$ with the property that for all $1\leq i\leq  l $ and $1\leq j\leq n_{i}$, there is a (possibly empty) open set $U_{i,k}\supset B_{i,k}$ in $X_{i}$ such that if $x\in U_{i,k}$, then $f_{i}(x)$ has zero crosses at indices $k,k+M,\ldots,k+(N-1)M$ and a block point at index $k$. Then, there exists a unitary $V\in A$ with the following properties:
	\begin{enumerate}
		\item for all $1\leq i\leq l $ and $1\leq k\leq n_{i}$, there are open sets $\mathcal{O}_{i,k}\supset B_{i,k}$ in $X_{i}$ such that $V_{i}(x)f_{i}(x)V_{i}(x)^{*}$ has zero crosses at indices $k,k+1,\ldots,k+N-1$ whenever $x\in \mathcal{O}_{i,k}$;
		\item$\mathfrak{r}(V_{i}(x)f_{i}(x)V_{i}(x)^{*})\leq \mathfrak{r}(f_{i}(x))+2$ for all $1\leq i\leq  l $ and $x\in X_{i}$.
	\end{enumerate}

Suppose $A$ is a DSH algebra of length $ l $. Suppose $M\in\mathbb{N}$ and $K:=\{K_{1}< K_{2}<\cdots<K_{m}\}$ are such that $K_{1}\geq 0$, $K_{m}<\mathfrak{s}(A)-M$, and $K_{t+1}-K_{t}\geq M$ for $1\leq t < m$. Suppose that for each $1\leq i\leq  l $ and $1\leq j\leq n_{i}$, we have a set $F_{i,j}\subset X_{i}$ that is closed in $X_{i}$ and disjoint from each set $B_{i,j-K_{t}}$ (see 2.7) for $1\leq t\leq m$. Then, there is a function $\Theta\in A$ such that:
	\begin{enumerate}
		\item for all $1\leq i\leq  l $ and $x\in X_{i}$, $\Theta_{i}(x)$ is a diagonal matrix with entries in $[0,1]$ whose final $M$ diagonal entries are all $0$, and such that at most one of every $M$ consecutive diagonal entries is non-zero;
		\item for all $1\leq i\leq  l $, $1\leq j\leq n_{i}$, and $x\in F_{i,j}$, we have $\Theta_{i}(x)_{j,j}=0$;
		\item for all $1\leq i\leq  l $ and $1\leq j\leq n_{i}$, there is a (possibly empty) open subset $U_{i,j}\subset X_{i}$ containing $B_{i,j}$ with the property that if $x\in U_{i,j}$, then $\Theta_{i}(x)_{j+K_{t},j+K_{t}}=1$ for all $1\leq t\leq m$. 
	\end{enumerate}

Suppose $A$ is a DSH algebra of length $ l $. Suppose $M\in\mathbb{N}$ and $K:=\{K_{1}< K_{2}<\cdots<K_{m}\}$ are such that $K_{1}\geq 0$, $K_{m}<\mathfrak{s}(A)-M$, and $K_{t+1}-K_{t}\geq M$ for $1\leq t < m$. Then, there is a function $\Phi\in A$ such that:
	\begin{enumerate}
		\item for all $1\leq i\leq  l $ and $x\in X_{i}$, $\Phi_{i}(x)$ is a diagonal matrix with entries in $[0,1]$ whose final $M$ diagonal entries are all $0$, and such that at most one of every $M$ consecutive diagonal entries is non-zero;
		\item for all $1\leq i\leq \ell$ and $1\leq j\leq n_{i}$: $\Phi_{i}(x)_{j,j}=1$ if and only if there is a $1\leq t\leq m$ such that $x\in B_{i,j-K_{t}}$. 
	\end{enumerate}
